from PIL import Image

def detect_finder_patterns(file_path):
    img = Image.open(file_path)
    pixels = img.load()
    matches = []
    for size in [7, 5, 3]:
        for r in [0, img.height-size]:
            for c in [0, img.width-size]:
                count_black = 0
                for y in range(size):
                    for x in range(size):
                        if pixels[c+x, r+y] == 0:
                            count_black += 1
                if count_black > size*size*0.8:  # mostly black block
                    matches.append({'pos': (r,c), 'size': size})
    return matches

if __name__ == '__main__':
    patterns = detect_finder_patterns('/home/ctfplayer/ctf_files/qr_qr_29x29_inv.png')
    print('Detected possible finder patterns:', patterns)

